333	SdfLayer::_WaitForInitializationAndCheckIfSuccessful()
334	{
335	    // Note: the caller is responsible for holding a reference to this
336	    // layer, to keep it from being destroyed out from under us while
337	    // blocked on the mutex.
338	
339	    // Drop the GIL in case we might have it -- if the layer load happening in
340	    // another thread needs the GIL, we'd deadlock here.
341	    TF_PY_ALLOW_THREADS_IN_SCOPE();
342	
343	    // Wait until _initializationComplete is set to true.  If the layer is still
344	    // being initialized, this will be false, blocking progress until
345	    // initialization completes.
346	    while (!_initializationComplete) {
347	        // XXX: Disabled for now due to intermittent crashes.
348	        //_initDispatcher.Wait();
349	        std::this_thread::yield();
350	    }
351	
352	    // For various reasons, initialization may have failed.
353	    // For example, the sdf text format parser may have hit a syntax error,
354	    // or transferring content from a source layer may have failed.
355	    // In this case _initializationWasSuccessful will be set to false.
356	    // The callers of this method are responsible for checking the result
357	    // and dropping any references they hold.  As a convenience to them,
358	    // we return the value here.
359	    return _initializationWasSuccessful.value();
